        node("legacy", null, {
          input: 20,
          output: 999,
          cacheRead: 30,
          cacheCreation: 40,
        }),
      ),
    ).toBe(90);
  });

  describe("isContextCompacted", () => {
    test("detects continuation summary marker in question", () => {
